import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner input = new Scanner(System.in)) {
            int copies = input.nextInt();
            if (copies > 0) {
                System.out.println("Available");
            } else {
                System.out.println("Wait");
            }
        }
    }
}
